#!/usr/bin/env python3
"""Render the versioned scaling TSV as a compact Markdown comparison."""

from __future__ import annotations

import csv
import pathlib
import sys


def main() -> None:
    source = pathlib.Path(sys.argv[1])
    destination = pathlib.Path(sys.argv[2])
    with source.open(newline="") as stream:
        rows = list(csv.DictReader(stream, delimiter="\t"))

    lines = [
        "# Versioned performance snapshot",
        "",
        "Generated by `benchmark/run_versioned_performance.sh` with two Julia threads.",
        "Absolute timings are host-specific; ranges are the minimum--maximum over warmed repetitions.",
        "Allocation counts and scaling are the hardware-independent CI guardrails.",
        "",
        "## Environment",
        "",
    ]
    environments = []
    for row in rows:
        environment = (
            row["julia_version"], row["source_revision"], row["threads"],
            row["blas_threads"], row["cpu"], row["repetitions"],
        )
        if environment not in environments:
            environments.append(environment)
    lines.extend([
        "| Julia | Source revision | Threads | BLAS | CPU | Repetitions |",
        "|---|---|---:|---:|---|---:|",
    ])
    for version, source_revision, threads, blas, cpu, repetitions in environments:
        lines.append(
            f"| {version} | `{source_revision}` | {threads} | {blas} | "
            f"{cpu} | {repetitions} |"
        )
    lines.extend([
        "",
        "## Measurements",
        "",
        "| Julia | Benchmark | n | Storage | Median ms | Range ms | Bytes |",
        "|---|---|---:|---|---:|---:|---:|",
    ])
    for row in rows:
        lines.append(
            f"| {row['julia_version']} | {row['benchmark']} | {row['n']} | "
            f"{row['storage']} | {float(row['median_ms']):.4f} | "
            f"{float(row['minimum_ms']):.4f}--{float(row['maximum_ms']):.4f} | "
            f"{row['bytes']} |"
        )
    lines.append("")
    destination.write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
